var t=`0798-potjiekos`;var n=`world-0798`;var s=`ZA`;var a=`southern-africa`;var o=4;var r=134;var l={en:`Potjiekos`,ua:`Потджикос`};var g={en:`Potjiekos is a South Africa classic prepared with lamb, yellow onion, carrot, potato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Потджикос, страва кухні країни Південно-Африканська Республіка зі складниками: ягнятина, жовта цибуля, морква, картопля. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 13 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 13 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:13,i:[[`lamb`,750,`g`],[`yellow-onion`,190,`g`],[`sunflower-oil`,45,`ml`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:12,i:[[`carrot`,240,`g`],[`potato`,420,`g`],[`green-beans`,280,`g`],[`tomato`,320,`g`]]},{en:`Keep vegetables in distinct layers over browned lamb, add stock, cover and simmer gently without repeated stirring until the potjiekos is tender.`,ua:`Залиште овочі окремими шарами поверх підрум’яненої баранини, влийте бульйон, накрийте й повільно тушкуйте без частого перемішування до м’якості.`,t:[`braising`],m:105,i:[[`beef-stock`,750,`ml`],[`dried-thyme`,4,`g`],[`bay-leaf`,2,`leaf`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,20,`g`]]}];var h={slug:t,id:n,country:`ZA`,region:a,servings:4,minutes:134,title:l,text:g,steps:d};export{s as country,h as default,n as id,r as minutes,a as region,o as servings,t as slug,d as steps,g as text,l as title};